'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "hconcat": [
    {
      "width": 108.0,
      "height": 108.0,
      "layer": [
        {
          "mark": {
            "type": "arc",
            "innerRadius": 35.64,
            "outerRadius": 51.839999999999996,
            "padAngle": 0.02,
            "cornerRadius": 3
          },
          "encoding": {
            "theta": {
              "field": "Pilot Appointments",
              "type": "quantitative",
              "stack": true
            },
            "order": {
              "field": "ord",
              "type": "quantitative"
            },
            "color": {
              "field": "Delivery Status",
              "type": "nominal",
              "scale": {
                "domain": [
                  "Delivered",
                  "Failed",
                  "Pending"
                ],
                "range": [
                  "#1BAF7A",
                  "#E34948",
                  "#A7B1C2"
                ]
              },
              "legend": null
            },
            "tooltip": [
              {
                "field": "Delivery Status",
                "type": "nominal"
              },
              {
                "field": "Pilot Appointments",
                "type": "quantitative",
                "format": ",.0f"
              }
            ]
          },
          "transform": [
            {
              "calculate": "indexof([''Delivered'', ''Failed'', ''Pending''], datum[''Delivery Status''])",
              "as": "ord"
            }
          ]
        },
        {
          "transform": [
            {
              "joinaggregate": [
                {
                  "op": "sum",
                  "field": "Pilot Appointments",
                  "as": "tot"
                }
              ]
            },
            {
              "filter": "datum[''Delivery Status''] == ''Delivered''"
            },
            {
              "calculate": "format(datum[''Pilot Appointments''] / datum.tot, ''.1%'')",
              "as": "label"
            }
          ],
          "mark": {
            "type": "text",
            "fontSize": 14.040000000000001,
            "fontWeight": 600,
            "color": "#101828",
            "dy": -6
          },
          "encoding": {
            "text": {
              "field": "label"
            }
          }
        },
        {
          "transform": [
            {
              "joinaggregate": [
                {
                  "op": "sum",
                  "field": "Pilot Appointments",
                  "as": "tot"
                }
              ]
            },
            {
              "filter": "datum[''Delivery Status''] == ''Delivered''"
            },
            {
              "calculate": "format(datum[''Pilot Appointments''] / datum.tot, ''.1%'')",
              "as": "label"
            }
          ],
          "mark": {
            "type": "text",
            "fontSize": 9.5,
            "color": "#667085",
            "dy": 11.719999999999999
          },
          "encoding": {
            "text": {
              "value": "delivered"
            }
          }
        }
      ]
    },
    {
      "width": 237.0,
      "height": 72,
      "transform": [
        {
          "joinaggregate": [
            {
              "op": "sum",
              "field": "Pilot Appointments",
              "as": "tot"
            }
          ]
        },
        {
          "calculate": "indexof([''Delivered'', ''Failed'', ''Pending''], datum[''Delivery Status''])",
          "as": "ord"
        },
        {
          "calculate": "format(datum[''Pilot Appointments''], '',.0f'')",
          "as": "vtxt"
        },
        {
          "calculate": "format(datum[''Pilot Appointments''] / datum.tot, ''.1%'')",
          "as": "ptxt"
        },
        {
          "calculate": "datum[''Delivery Status'']",
          "as": "lab"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "point",
            "filled": true,
            "size": 70,
            "shape": "circle"
          },
          "encoding": {
            "y": {
              "field": "ord",
              "type": "ordinal",
              "axis": null,
              "scale": {
                "domain": [
                  0,
                  1,
                  2
                ],
                "padding": 0.6
              }
            },
            "x": {
              "value": 6
            },
            "color": {
              "field": "Delivery Status",
              "type": "nominal",
              "scale": {
                "domain": [
                  "Delivered",
                  "Failed",
                  "Pending"
                ],
                "range": [
                  "#1BAF7A",
                  "#E34948",
                  "#A7B1C2"
                ]
              },
              "legend": null
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "fontSize": 10.5,
            "color": "#344054"
          },
          "encoding": {
            "y": {
              "field": "ord",
              "type": "ordinal",
              "axis": null,
              "scale": {
                "domain": [
                  0,
                  1,
                  2
                ],
                "padding": 0.6
              }
            },
            "x": {
              "value": 16
            },
            "text": {
              "field": "lab"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "right",
            "fontSize": 10.5,
            "fontWeight": 600,
            "color": "#101828"
          },
          "encoding": {
            "y": {
              "field": "ord",
              "type": "ordinal",
              "axis": null,
              "scale": {
                "domain": [
                  0,
                  1,
                  2
                ],
                "padding": 0.6
              }
            },
            "x": {
              "value": 193.0
            },
            "text": {
              "field": "vtxt"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "right",
            "fontSize": 10,
            "color": "#667085"
          },
          "encoding": {
            "y": {
              "field": "ord",
              "type": "ordinal",
              "axis": null,
              "scale": {
                "domain": [
                  0,
                  1,
                  2
                ],
                "padding": 0.6
              }
            },
            "x": {
              "value": 237.0
            },
            "text": {
              "field": "ptxt"
            }
          }
        }
      ]
    }
  ],
  "spacing": 14,
  "autosize": {
    "type": "pad"
  },
  "config": {
    "concat": {
      "spacing": 14
    }
  }
}'

